function wastaBridge(){const selected=SALES_DATA.accounts.find(x=>x.id===activeRoute)||SALES_DATA.accounts[0];return `<section class="wasta-map"><div class="eyebrow">MIDDLE EAST / RELATIONSHIP ARCHITECTURE</div><h2>${st('两类入口，一条可交付的信任链。','Two routes. One deliverable chain of trust.')}</h2><p class="wasta-legend">${st('实线框为企业/生态直接入口，虚线框为可触达的战略关系路径；两类资源均可启动，所需时间、组织方式与投入不同。箭头表示项目推进路径。','Solid outlines show direct enterprise / ecosystem access; dashed outlines show reachable strategic relationship routes. Both can be activated, with different timelines, coordination and resources. Arrows show project progression.')}</p><div class="route-row"><span>${st('直接入口','DIRECT ACCESS')}</span><div>${SALES_DATA.accounts.filter(x=>x.access==='direct_confirmed').map(a=>`<button data-route="${a.id}" class="${a.id===activeRoute?'active':''}" aria-pressed="${a.id===activeRoute}">${accountName(a)}</button>`).join('')}</div></div><div class="route-row strategic"><span>${st('关系通路','RELATIONSHIP ROUTES')}</span><div>${SALES_DATA.accounts.filter(x=>x.kind==='strategic').map(a=>`<button data-route="${a.id}" class="${a.id===activeRoute?'active':''}" aria-pressed="${a.id===activeRoute}">${accountName(a)}</button>`).join('')}</div></div><div class="trust-chain">${[['信任引荐','Trusted introduction'],['业务赞助','Business sponsorship'],['共同工作组','Joint working group'],['采购与履约','Procurement and delivery']].map((x,i)=>`<div><b>0${i+1}</b><strong>${st(x[0],x[1])}</strong>${i<3?'<span>→</span>':''}</div>`).join('')}</div><div class="route-focus" aria-live="polite"><small>${selected.id} / ${selected.access==='direct_confirmed'?st('已确认直接入口','Confirmed direct access'):st('可触达战略关系','Reachable strategic relationship')}</small><h3>${accountName(selected)}</h3><p>${sv(selected.social_role)}</p><p><b>${st('先推进：','First move: ')}</b>${sv(selected.next)}</p></div></section>`;}
function wastaRules(){return `<section class="editorial-section">${sectionHeading('WASTA / SOCIAL CAPITAL INTO EXECUTION',st('把关系规则，转成可兑现的合作安排。','Turn relationship principles into executable cooperation.'),st('关系、互惠、层级与长期信任是理解背景；以下为执行建议，具体节奏以对方意愿、国别和企业流程为准。','Relationships, reciprocity, hierarchy and lasting trust provide context. The actions below are recommendations, subject to counterpart preference and local procedures.'))}<div class="wasta-principles">${[
['信任前置','Trust first','正式报价前明确引荐人、关系赞助人和可讨论议题；会前取得对材料接收和转发范围的同意。','Before a formal quote, identify the introducer, sponsor and agreed topic; obtain permission for receipt and onward sharing of materials.','交付：一页议题＋受邀角色＋披露范围','Output: one-page theme, invitees and disclosure scope'],
['互惠可兑现','Deliverable reciprocity','用业务诊断、技术演示、本地培训和持续服务贡献价值，承诺有负责人、有交付日期。','Contribute discovery, demonstrations, local training and continuing service; assign an owner and date to each commitment.','交付：双方贡献清单＋兑现记录','Output: contribution list and fulfillment record'],
['层级与工作层衔接','Connect sponsors to working teams','尊重既有介绍链；请赞助方指定运营、技术和采购角色。会后向引荐人反馈进度，避免绕开关系链单独施压。','Respect the introduction chain; ask the sponsor to nominate operations, technical and purchasing roles. Keep the introducer informed without pressuring the buyer.','交付：赞助人—业务拥有者—采购角色图','Output: sponsor, process-owner and procurement map'],
['长期信任分段兑现','Build trust through small outcomes','先完成小范围、可检验成果，再讨论更大投入；出现延期及时说明并协商重排。同步建立多角色关系，降低单点依赖。','Deliver a small testable outcome before expanding investment. Explain delays and agree revised plans; build multi-role relationships to reduce dependency.','交付：小成果＋复盘＋下一阶段共识','Output: small outcome, review and next-stage agreement']
].map((x,i)=>`<article><span>0${i+1}</span><h3>${st(x[0],x[1])}</h3><p>${st(x[2],x[3])}</p><small>${st(x[4],x[5])}</small></article>`).join('')}</div><p class="sales-small">${st('应用原则：关系用于促成受邀沟通、减少信息不对称并建立承诺；合同、采购权限、竞争程序和付款责任照常确认。顾问、培训、活动等费用只对应真实工作与交付，不作为关系费用的换名包装。','Use relationships to enable invited dialogue, reduce information gaps and build commitments. Confirm contracts, purchasing authority, procurement procedures and payment responsibilities. Advisory, training and event fees must reflect real work and outputs, not relabeled influence payments.')}</p><p class="source-inline">${st('背景依据：所供Wasta分析与组织研究；具体工作安排为方案建议。','Context: supplied Wasta analysis and organizational research; specific operating steps are proposed.')} <a href="https://www.cambridge.org/core/journals/management-and-organization-review/article/wasta-advancing-a-holistic-model-to-bridge-the-micromacro-divide/84B909B307A93B7703A654F2E649E064" target="_blank" rel="noopener">${st('研究参考 ↗','Research reference ↗')}</a></p></section>`;}
function salesOverview(){return intro('BUBIX / MIDDLE EAST RELATIONSHIPS',st(FIXED_OPENING.zh,FIXED_OPENING.en),st('MAKE TRUST EASY. 聚焦海湾家族集团、地产运营、贸易生态与战略关系网络，把在地资源接到具体业务、采购和回款。','MAKE TRUST EASY. Connect Gulf family groups, property operations, trade ecosystems and strategic networks to defined business needs, procurement and collections.'))+`<div class="sales-cover"><div><div class="eyebrow">MIDDLE EAST ONLY / V3.5</div><h2>${st('四个直接入口，<br>四条战略关系通路。','Four direct routes.<br>Four strategic relationship paths.')}</h2><p>${st('Emaar、Al-Futtaim、Saif Belhasa、DMCC为已确认直接入口；沙特王室、主权投资商务圈层与泛阿拉伯资源同样可触达。以产品议题组织对话，以时间和成本推动项目。','Emaar, Al-Futtaim, Saif Belhasa and DMCC are confirmed direct routes. Saudi royal, sovereign-investment-circle and pan-Arab resources are also reachable. Organize dialogue around product propositions and invest time and resources to develop projects.')}</p><div class="proof-links">${sbutton('resources','02 打开关系与资源图谱','02 Relationship and resource map')}${sbutton('execution','03 查看关系牵引的对接计划','03 Trust-led execution plan')}</div></div><img src="assets/brand-gateway-v3.webp" width="1672" height="941" alt="${st('海湾信任之门品牌概念','Gulf gateway brand concept')}"></div><div class="sales-counts">${[['4','已确认直接入口','Confirmed direct routes'],['4','战略关系通路','Strategic relationship routes'],['3','三年规划愿景','Three-year planning vision'],['12–24','首轮推进月数','Initial development months']].map(x=>`<div><b>${x[0]}</b><span>${st(x[1],x[2])}</span></div>`).join('')}</div>${salesNote()}${planningVision()}${strategicFrame()}${wastaBridge()}<section class="editorial-section">${sectionHeading('RELATIONSHIP → BUSINESS → CASH',st('资源可达，产品切入，项目落地。','Reachable resources. Product-led entry. Executable projects.'))}<div class="sales-sequence">${[['02','resources','中东关系与资源','Middle East relationships','四核心入口＋四战略通路','Four core routes + four strategic paths'],['03','execution','信任与对接节奏','Trust-led execution','引荐、赞助、工作组与共创','Introduction, sponsorship and co-design'],['04','pipeline','商机与签约','Pipeline and contracts','合格需求、有价方案、正式合同','Qualified need, priced SOW and contract'],['05','delivery','交付与验收','Delivery and acceptance','可检验成果、交接与本地能力','Testable outcome, handover and capability'],['06','collections','回款与长期关系','Cash and sustained trust','付款责任、进度反馈与续期','Payments, progress feedback and renewal']].map(x=>`<button data-go="${x[1]}"><span>${x[0]}</span><strong>${st(x[2],x[3])}</strong><small>${st(x[4],x[5])}</small></button>`).join('')}</div></section>`;}
function salesResources(){const items=SALES_DATA.accounts.filter(x=>salesKind==='all'||x.kind===salesKind);return intro('02 / MIDDLE EAST RESOURCES & WASTA',st('把人脉网络，接到真正的业务主体。','Connect relationship networks to accountable businesses.'),st('四个直接入口与四条战略通路分别展示。关系角色、业务角色、采购权与付款责任保持独立；不按人脉头衔或覆盖国家数放大客户数量。','Show four direct routes and four strategic paths separately. Relationship roles, business ownership, purchasing authority and payment remain distinct; titles and country coverage do not multiply customers.'))+salesNote()+wastaBridge()+productLedPaths()+wastaRules()+`<div class="sales-filters" aria-label="${st('筛选资源角色','Filter resource roles')}">${[['all',st('全部8条路径','All 8 routes')],...Object.entries(kinds)].map(([k,v])=>`<button data-kind="${k}" class="${salesKind===k?'active':''}" aria-pressed="${salesKind===k}">${v}</button>`).join('')}</div><div class="account-grid">${items.map(a=>`<article class="account-card" id="account-${a.id}"><div class="account-meta"><span>${a.id} / ${a.priority}</span><span>${kinds[a.kind]}</span></div><h2>${esc(accountName(a))}</h2><div class="account-status">${a.access==='direct_confirmed'?st('直接入口可对接 / 2026.10.28；产品与预算按工作包推演','Direct access confirmed / 2026.10.28; infer product scope and budget from work packages'):st('战略关系可触达 / 2026.10.28；按议题组织、投入时间与商务资源','Strategic access confirmed / 2026.10.28; activate through a focused theme, time and commercial resources')} · ${a.window}</div><h3>${st('Wasta角色与入口','Wasta role and entry')}</h3><p>${sv(a.social_role)}</p><p>${sv(a.entry)}</p><h3>${st('可承接的业务议题','Proposed business theme')}</h3><p>${sv(a.offer)}</p><details><summary>${st('展开互惠价值、推进动作与条件','Reciprocal value, actions and conditions')}</summary><h3>${st('可兑现的合作价值','Deliverable reciprocal value')}</h3><p>${sv(a.reciprocity)}</p><h3>${st('下一步','Next step')}</h3><p>${sv(a.next)}</p><h3>${st('进入企业项目的条件','Enterprise-project gate')}</h3><p>${sv(a.gate)}</p><div class="account-stop">${sv(a.stop)}</div><p class="source-inline">${st('来源类别：','Source category: ')}${a.source.map(id=>{const x=SALES_DATA.sources.find(v=>v.id===id);return x?`<a href="${x.url}" target="_blank" rel="noopener">${id} ↗</a>`:id}).join(' · ')}</p></details></article>`).join('')}</div>`;}
function strategicFrame(){return `<section class="editorial-section">${sectionHeading('STRATEGY / PRODUCTS × RELATIONSHIPS × EXECUTION',st('以产品定义机会，以资源打开市场。','Define the opportunity through products. Open markets through relationships.'),st('方案用于决定从哪里切入、投入什么、如何形成项目；按产品价值反推客户议题与预算区间，再通过商务推进逐步细化。','This plan selects entry points, resources and project paths. Product value informs account themes and indicative budgets, refined through commercial engagement.'))}<div class="campaign-flow">${[
['资源前提','Relationship foundation','四个企业/生态入口与四条战略关系路径均可触达，排期和投入决定推进速度。','All four enterprise / ecosystem routes and four strategic relationship routes are reachable; scheduling and investment determine pace.'],
['产品推演','Product-led planning','以场景、工作量、集成复杂度和持续服务反推需求、报价与收入组合；经营规模与总部成本采用规划参数，历史财务不作为已证实基准。','Infer demand, pricing and revenue mix from use cases, effort, integration complexity and ongoing service. Operating scale and HQ costs use planning assumptions; historical financials are not a verified baseline.'],
['执行落点','Execution focus','用一页议题、五分钟演示和有价工作包进入商务对话，推进工作组、合同、交付和回款。','Enter dialogue with a one-page theme, five-minute demo and priced scope; progress to a working team, contract, delivery and cash.']
].map(x=>`<section><h3>${st(x[0],x[1])}</h3><p>${st(x[2],x[3])}</p></section>`).join('')}</div></section>`;}
function productLedPaths(){return `<section class="editorial-section">${sectionHeading('PRODUCT → ACCOUNT → PROJECT',st('四个切口，两条增长主线。','Four entry points. Two growth engines.'),st('以下是产品与业务适配推演；预算按交付工作包反推，用于首轮商务讨论。','The following are proposed product / business fits. Budgets are derived from delivery scopes for initial commercial discussion.'))}<div class="tablewrap"><table><thead><tr><th>${st('入口','Route')}</th><th>${st('产品切口','Product wedge')}</th><th>${st('首轮交付','First deliverable')}</th><th>${st('后续规模化','Expansion path')}</th></tr></thead><tbody>${[
['Emaar','工程验收、供应商履约与资产运营记录','Project acceptance, supplier performance and asset-operation records','选定一个流程，演示多方状态与记录追溯','Demonstrate shared status and traceability for one workflow','项目模板→多项目接入→年度运维','Project template → multiple projects → annual support'],
['Al-Futtaim','汽车/供应商凭证与跨业务单元对账','Automotive / supplier credentials and cross-unit reconciliation','梳理一个业务单元的凭证与对账工作流','Map one business unit credential / reconciliation flow','单元试点→跨部门复制→持续服务','Unit pilot → cross-department reuse → recurring service'],
['Saif Belhasa','产业履约记录与本地技术服务协同','Industrial performance records and local technology-service cooperation','集团场景诊断或与本地技术团队共做演示','Group workflow discovery or a joint local-team demo','集团应用→联合交付→合作运营','Group application → joint delivery → cooperative operations'],
['DMCC','贸易凭证互操作与成员企业协作','Trade-credential interoperability and member collaboration','与既有Tradeflow等系统互补的场景演示','Demonstrate a complementary use case alongside systems such as Tradeflow','成员项目→贸易生态连接→按量服务','Member projects → ecosystem links → usage-based services']
].map(x=>`<tr><td>${x[0]}</td><td>${st(x[1],x[2])}</td><td>${st(x[3],x[4])}</td><td>${st(x[5],x[6])}</td></tr>`).join('')}</tbody></table></div><div class="two"><section class="card"><h3>${st('B线 / 企业场景：形成第一批可交付项目','Engine B / enterprise use cases: establish deliverable projects')}</h3><p>${st('从四个核心入口进入场景诊断与付费验证；诊断USD10,000–20,000、约6个有效周的受控试点USD40,000–65,000为现有工作包规划区间。目标是形成可复制模板，再接实施、运维和增量服务。','Use the four core routes for discovery and paid validation. Existing scope assumptions are USD10,000–20,000 for discovery and USD40,000–65,000 for a bounded pilot with about six active workweeks. Build reusable templates, then implementation, support and incremental services.')}</p></section><section class="card"><h3>${st('A线 / 战略平台：培育更大合作空间','Engine A / strategic platforms: develop larger cooperation')}</h3><p>${st('王室、主权投资商务圈层及泛阿拉伯资源承担高层议题与产业组织牵引；以企业场景为演示载体，提出行业平台、节点网络和本地联合运营方案。组织多个参与方和平台采购，需另行配置时间、团队与资本。','Royal, sovereign-investment-circle and pan-Arab routes lead executive themes and industry organization. Use enterprise scenarios to demonstrate an industry platform, node network and local joint operations. Multi-party organization and platform procurement require their own time, team and capital.')}</p></section></div><p class="sales-small">${st('以可触达资源为基础，先形成有吸引力、可交付、能报价的产品方案；通过对接反馈逐步细化需求、预算和合作范围。','Start with reachable relationships and an attractive, deliverable, priceable product proposition. Refine needs, budgets and cooperation scope through engagement.')}</p></section>`;}
const salesGates=[['S0','目标资源','Target route','可触达资源与产品议题匹配，形成首轮对接方案','Match reachable resources to product themes and prepare the initial proposition'],['S1','有效接洽','Verified contact','近期沟通与具体业务负责人；不只是名片','Recent communication with a relevant process owner, not a business card'],['S2','需求合格','Qualified need','问题、买方、数据、预算路径、时间明确','Confirmed problem, buyer, data, budget path and timing'],['S3','有价方案','Priced SOW','明确范围、报价、验收、采购及付款条件','Defined scope, price, acceptance, procurement and payments'],['S4','有效签约','Effective contract','双方有权签署且合同生效；记录净合同额','Authorized signatures and effective contract; record net value'],['S5','交付验收','Accepted delivery','取得合同约定的验收证据；财务确认收入','Contractual acceptance evidence; finance determines revenue'],['S6','实际回款','Cash received','银行到账与合同/发票勾稽；不是口头付款承诺','Bank receipt reconciled to contract / invoice, not a payment promise']];
function wastaRoles(){return `<section class="editorial-section">${sectionHeading('ONE MEETING / FIVE DISTINCT ROLES',st('每场会先确定五种角色。','Identify five distinct roles for each engagement.'))}<div class="delivery-weeks">${[
['引荐人','Introducer','负责进入对话与介绍范围；约定反馈方式。','Enables the introduction and agrees the feedback scope.'],['关系/业务赞助人','Sponsor','认可议题并指定对口团队；不默认拥有采购权。','Supports the theme and nominates a team; procurement authority is separate.'],['业务拥有者','Process owner','定义痛点、数据权限、流程和验收。','Owns the problem, data authority, workflow and acceptance.'],['采购/法务','Procurement / legal','确认程序、合同、供应商准入与责任。','Confirms procedures, contract, onboarding and responsibilities.'],['付款/财务','Finance / payer','确认付款法人、资金与回款节点。','Confirms paying entity, funding and payment milestones.']
].map((x,i)=>`<section><b>0${i+1}</b><h3>${st(x[0],x[1])}</h3><p>${st(x[2],x[3])}</p></section>`).join('')}</div></section>`;}
let planCase=new URLSearchParams(location.search).get('scenario')==='delay6'?'delay6':'base';
const FIXED_OPENING={zh:'以信任打开对话，以履约沉淀关系。',en:'Trust opens dialogue. Delivery sustains relationships.'};
const FIXED_BRAND_LINE='MAKE TRUST EASY.';
function planningVision(){return `<section class="editorial-section">${sectionHeading('THREE YEARS / TRUST TO SCALE',st('第一年扎根，第二年交付，第三年复制。','Year one: establish. Year two: deliver. Year three: replicate.'),st('以三年愿景统领；12–24个月为首轮市场建设与项目落地主周期。时间从团队获得授权与启动资源后的M1起算。','A three-year vision, with12–24months for initial market development and delivery. M1 starts with an authorized team and mobilization resources.'))}<div class="campaign-flow">${[
['Y1 / 进入与共识','Y1 / entry and alignment','前两个月熟悉产品、梳理关系并建立相处节奏；随后逐步进入议题会、工作组与范围讨论。基准在M5开始首项付费诊断，M9启动受控试点。','Use the first two months for product orientation, relationship visits and working rhythm. Progress to themes, teams and scope. Base case: first paid discovery startsM5, bounded pilotM9.'],
['Y2 / 生产与服务','Y2 / production and services','在既有试点与共识上处理系统、安全、采购和上线安排；基准M18完成首个生产项目，开始服务收入。沙特平台合作继续培育。','Resolve systems, security, procurement and rollout around the initial use case. Base case: first production acceptanceM18, followed by service revenue. Continue Saudi platform development.'],
['Y3 / 复制与平台','Y3 / replication and platform','以可复用模板复制企业项目，逐步形成持续服务；产业平台合作作为独立上行空间，另配商务、交付与资本，不计入企业底盘。','Reuse templates across enterprise projects and recurring services. Industry-platform cooperation is a separate upside, with its own commercial, delivery and capital resources, outside the enterprise base.']
].map(x=>`<section><h3>${st(x[0],x[1])}</h3><p>${st(x[2],x[3])}</p></section>`).join('')}</div></section>`;}
const horizonPhases=[
{d:'M1–2',title:['进入与关系磨合','Orientation and relationship rhythm'],r:['熟悉布比产品与现有关系的相处方式；安排礼节拜访、倾听与小范围交流，理解对方关注点。','Learn BUBIX products and how existing relationships work. Use introductory visits, listening and focused dialogue to understand counterpart priorities.'],p:['完成四份议题初稿和一个共用演示；将客户问题假设与产品边界对应。','Prepare four initial theme briefs and one reusable demo, mapping problem hypotheses to product boundaries.'],c:['以建立熟悉度、形成下一次对话为主；首月不以付费转化为目标。','Build familiarity and a reason for the next conversation. Paid conversion is not the first-month goal.'],out:['关系节奏图、产品议题卡、出访与材料计划','Relationship rhythm, product theme briefs, travel and material plan'],g:['形成可持续对话后再进入深度议题；外部预约未就绪时继续内部准备。','Deepen themes as a sustainable dialogue develops; use scheduling gaps for internal preparation.']},
{d:'M3–4',title:['议题共识与预约','Theme alignment and working meetings'],r:['围绕一个共同问题安排工作会；由高层关系逐步连接到业务与技术负责人。','Arrange working sessions around one shared problem, connecting senior relationships to process and technical owners.'],p:['准备流程图、授权演示与价值说明；反复修改正常计入售前负荷。','Prepare process maps, authorized demos and value briefs, allowing for iteration within presales capacity.'],c:['以两条活跃议题为优先，争取进入诊断范围与采购讨论；允许客户内部排期。','Prioritize two active themes and advance toward discovery scope and purchasing discussions, allowing for counterpart calendars.'],out:['两条重点议题、工作组草案、初步范围与预算','Two priority themes, working-team draft, initial scope and budget'],g:['用议题推进情况调整安排；会议延期时切换到另一核心入口。','Adjust pacing to theme momentum; shift effort to another core route if meetings slip.']},
{d:'M5–8',title:['诊断与方案共创','Discovery and proposition design'],r:['通过多轮交流建立工作层信任；尊重原有介绍链，逐步形成共同项目责任。','Build working-level trust over repeated discussions, respecting the introduction chain and shared ownership.'],p:['基准安排两项诊断分别从M5/M8启动；每项预留两个月客户日历。','Base case: two discovery scopes beginM5/M8, each allowing two calendar months.'],c:['形成有价诊断与试点方案；安全、数据及供应商程序纳入客户侧排期。','Develop priced discovery and pilot proposals; allow for customer security, data and supplier processes.'],out:['诊断成果、试点SOW、项目日历与责任表','Discovery outputs, pilotSOW, project calendar and ownership map'],g:['以可交付范围进入合同安排；排期卡住时复用共用材料，不继续无限定制。','Move bounded scope into contracting; reuse common materials rather than expanding unpaid custom work while schedules are blocked.']},
{d:'M9–12',title:['受控试点与年度复盘','Bounded pilot and year-one review'],r:['维持稳定反馈与拜访，不把频繁催促当作关系经营。','Maintain dependable updates and visits; pressure is not a substitute for relationship stewardship.'],p:['基准M9启动、M11完成首个试点；三个月客户日历包含等待、复核和返工缓冲。','Base case: first pilot startsM9 and completesM11. Three calendar months allow for waiting, review and rework.'],c:['按实际合同处理验收与收款；若客户顺延，切换延后情景并重排下一年度。','Manage acceptance and cash against contracts. Switch to the delayed case and replan the following year when customer schedules shift.'],out:['试点成果或有原因的滚动计划、年度费用与下一阶段安排','Pilot outcome or explained rolling plan, annual spending and next-stage schedule'],g:['把问题、合作状态和资金负荷放在一起复盘；首年不承诺生产平台全面落地。','Review cooperation, issues and funding together; full production-platform delivery is not a year-one commitment.']},
{d:'M13–18',title:['生产采购与首个上线','Production procurement and first rollout'],r:['将赞助关系转为持续工作机制，保持业务、安全、技术、采购多角色协作。','Translate sponsorship into an ongoing mechanism across business, security, technology and procurement.'],p:['基准M15启动首个生产实施、M18验收；复杂情形按4–8个月客户周期安排。','Base case: first production implementationM15–18; allow four-to-eight calendar months for more complex cases.'],c:['团队与收入同步扩张；生产团队按项目成本配置，避免提前堆积固定人员。','Scale capacity with delivery; resource production teams through project costs rather than premature fixed headcount.'],out:['生产版本、交接培训、服务范围与首期服务账单','Production release, handover, service scope and initial service billing'],g:['上线后复盘运行与服务负荷，再决定复制范围。','Review operations and support load before expanding replication.']},
{d:'M19–24',title:['集团复制与本地运营','Group replication and local operations'],r:['以兑现成果争取同集团或生态伙伴的下一项合作，维持长期互惠。','Use fulfilled commitments to open the next group or ecosystem opportunity and sustain reciprocal value.'],p:['基准第二年完成两个生产项目，逐步形成维护、订阅与本地协调能力。','Base case: two production acceptances in year two, building support, subscriptions and local coordination.'],c:['产业平台合作另行测算资本、治理与交付，进入三年愿景的扩张评审。','Assess platform capital, governance and delivery separately for the three-year expansion decision.'],out:['复用模板、持续服务、下一年度项目与组织计划','Reusable templates, recurring services and next-year project / organization plan'],g:['以容量、现金及合作质量决定Y3放量；延后情景允许结论后移。','ScaleY3 according to capacity, cash and cooperation quality; delayed cases move this decision later.']}
];
function calendarAndCapacity(){return `<section class="editorial-section">${sectionHeading('HUMAN CAPACITY / A ROLLING CALENDAR',st('留出时间，关系和交付才能走得长。','Leave room for relationships and delivery to last.'))}<div class="two"><section class="card"><h3>${st('每月20个工作日的配置示例','Illustrative allocation of20 working days')}</h3><p>${st('关系与外部会6天；准备及会后跟进5天；产品/交付协调4天；内部行政2天；未排满缓冲3天。缓冲用于休假、临时事务、返工及差旅后的恢复。这是配置样例。','Relationships and external meetings6days; preparation / follow-up5; product / delivery coordination4; internal administration2; unallocated buffer3. The buffer covers leave, personal contingencies, rework and post-travel recovery. This is an illustrative allocation.')}</p><p>${st('优先维持两个活跃业务议题；战略关系初期选一条重点路径，另外一条低频培育。总部售前按已排定人月介入。','Maintain two active business themes. Initially prioritize one strategic route and nurture a second at lower intensity. Schedule headquarters presales by allocated person-months.')}</p></section><section class="card"><h3>${st('按共同日历推进','Work to an agreed calendar')}</h3><p>${st('斋月、开斋节、宰牲节、夏季休假、差旅及审批会议都纳入实际排期；预留季度机动窗口，与对方约定下一步时间。','Include Ramadan, Eid holidays, summer leave, travel and approval meetings in actual schedules. Preserve quarterly flexibility and agree the next contact date with the counterpart.')}</p><p>${st('斋月保持联系并按对方节奏调整工作会；不把整个地区视为停工。具体工作周、假日及工作安排以当地机构日历为准。','Maintain contact during Ramadan and adapt meetings to counterpart preference. The region does not universally stop work. Use each organization’s actual working week, holidays and arrangements.')}</p><a href="https://u.ae/en/information-and-services/public-holidays-and-religious-affairs/public-holidays" target="_blank" rel="noopener">${st('阿联酋官方假日参考 ↗','UAE official holiday reference ↗')}</a> · <a href="https://www.hrsd.gov.sa/en/knowledge-centre/articles/312" target="_blank" rel="noopener">${st('沙特官方工作安排参考 ↗','Saudi official working-arrangement reference ↗')}</a></section></div></section>`;}
function contingencyPlan(){return `<section class="editorial-section">${sectionHeading('PLAN B / KEEP THE PATH, RESET THE PACE',st('客户有自己的时间，方案要有转弯的余地。','Customers have their own timing. The plan needs room to adapt.'))}<div class="tablewrap"><table><thead><tr><th>${st('出现的情况','Situation')}</th><th>${st('时间与业务调整','Schedule / business response')}</th><th>${st('投入如何调整','Resource response')}</th></tr></thead><tbody>${[
['会面或高层议题顺延4–8周','Meeting or executive theme slips4–8weeks','沿既有关系协商新窗口；切换另一核心入口，继续完善共用演示。','Agree a new window through the existing relationship; work another core route and improve reusable demos.','减少专属定制和非必要出访；维持低频、有价值的联系。','Reduce dedicated customization and nonessential visits; maintain useful, low-frequency contact.'],
['采购、数据或安全流程增加2–3个月','Procurement, data or security adds2–3months','将项目日历整体滚动；双方认可时先做独立付费诊断或沙盒验证。','Roll the project calendar; if mutually suitable, use independently priced discovery or sandbox work.','生产团队不提前进场；售前资源按月重排，避免等待期持续满配。','Do not mobilize production prematurely; reallocate presales monthly rather than holding full capacity idle.'],
['整体商业化顺延约6个月','Commercialization slips about6months','切换压力情景；首个试点可后移到Y2，保留关系和产品资产。','Use the stress case; the first pilot may move toY2 while relationships and product assets remain.','优先保留区域牵引与必要售前，复核6个月资金；暂停下一批扩张。','Retain core regional stewardship / presales, review six-month funding and pause the next expansion tranche.'],
['M12仍缺少共同项目路径','No shared project path byM12','复盘场景、合作主体和切入方式；在现有八条可触达资源内调整优先级。','Reassess the use case, partner and entry approach; reprioritize within the eight reachable routes.','次年转入轻量关系维护，明确重新启动的议题与时间；不无期限追加。','Move to light relationship stewardship and define a re-entry theme / window rather than indefinite spending.']
].map(x=>`<tr><td>${st(x[0],x[1])}</td><td>${st(x[2],x[3])}</td><td>${st(x[4],x[5])}</td></tr>`).join('')}</tbody></table></div><p class="sales-small">${st('延后6个月模型暂不假设节流成功，固定配置仍持续，便于看清资金压力；上述节流行动获定后，再替换月度成本。关系可触达是资源前提，预约和客户排期变化属于执行过程。','The six-month delayed model assumes fixed resources continue, exposing funding pressure before any savings. Replace monthly costs when savings actions are agreed. Relationships are reachable; changing appointments and customer schedules are execution realities.')}</p></section>`;}
function accountSchedule(){return `<section class="editorial-section">${sectionHeading('TWO ENGINES / DIFFERENT CLOCKS',st('企业项目先扎根，战略平台留出成熟期。','Establish enterprise projects. Allow strategic platforms to mature.'))}<div class="tablewrap"><table><thead><tr><th>${st('路径','Route')}</th><th>Y1</th><th>Y2</th><th>Y3</th></tr></thead><tbody>${[
['Emaar / Al-Futtaim / Saif Belhasa','关系经营、议题与诊断/试点','生产落地与同集团延展','模板复制与服务运营','Relationships, themes, discovery / pilot','Production and group expansion','Template replication and recurring service'],
['DMCC','生态议题、小型交流及成员转介','具名成员项目与系统互补','成员间复用与按量服务','Ecosystem themes and member referrals','Named-member projects and complementary systems','Cross-member reuse and usage services'],
[st('王室/产业关系','Royal / industry routes'),'持续拜访与共同议题','产业组织与合作架构','成熟议题进入平台评审','Visits and shared themes','Industry organization and partnership structure','Platform assessment as themes mature'],
[st('主权投资商务圈层','Sovereign-investment business circle'),'产业价值议题与专题交流','明确运营主体、治理与商业方案','独立决策的战略项目空间','Industry themes and focused dialogue','Operator, governance and commercial structure','Strategic projects through separate decisions'],
[st('泛阿拉伯顾问网络','Pan-Arab advisory network'),'专题交流和具名企业连接','跨区域企业合作','按能力复制与长期合作','Focused dialogue and named-enterprise links','Cross-regional enterprise cooperation','Replication within capacity and sustained cooperation']
].map(x=>`<tr><td>${x[0]}</td>${(salesEn?x.slice(4):x.slice(1,4)).map(z=>`<td>${z}</td>`).join('')}</tr>`).join('')}</tbody></table></div></section>`;}
function salesExecution(){const p=horizonPhases[salesPhase],tx=x=>st(x[0],x[1]);return intro('03 / 12–24 MONTHS · THREE-YEAR VISION',st('用足时间，把关系经营成持续业务。','Give relationships time to become sustained business.'),st('前365–730天是进入、共识与首批落地的主周期；Y3承接复制与平台合作。各阶段重叠、可后移，每季度滚动复盘。','The first365–730days cover entry, alignment and initial delivery. Y3 supports replication and platform cooperation. Stages overlap, may shift, and are reviewed quarterly.'))+`<section class="sales-roadmap"><div class="roadmap-tabs" role="tablist" aria-label="${st('选择推进阶段','Choose planning phase')}">${horizonPhases.map((x,i)=>`<button role="tab" data-phase="${i}" class="${i===salesPhase?'active':''}" aria-selected="${i===salesPhase}"><b>${x.d}</b><span>${tx(x.title)}</span></button>`).join('')}</div><div class="roadmap-deck"><div class="eyebrow">${p.d} / ${tx(p.title)}</div>${[['RELATIONSHIPS',p.r],['BUSINESS',p.p],['COMMERCIAL',p.c]].map(x=>`<div class="lane"><span>${x[0]}</span><p>${tx(x[1])}</p></div>`).join('')}<div class="roadmap-output"><strong>${st('阶段成果：','Stage output: ')}${tx(p.out)}</strong><p>${st('滚动安排：','Rolling arrangement: ')}${tx(p.g)}</p></div></div></section>${planningVision()}${calendarAndCapacity()}${accountSchedule()}${contingencyPlan()}${salesReadiness()}${wastaRoles()}`;}
function scenarioSwitch(){return `<div class="sales-filters" aria-label="${st('选择经营情景','Select planning case')}">${[['base','基准节奏','Base cadence'],['delay6','整体延后6个月','Six-month slip']].map(x=>`<button data-scenario="${x[0]}" aria-pressed="${planCase===x[0]}" class="${planCase===x[0]?'active':''}">${st(x[1],x[2])}</button>`).join('')}</div>`;}
function financialPath(){const c=STRATEGY_MODEL.cases[planCase];return `<section class="editorial-section">${sectionHeading('THREE-YEAR ENTERPRISE BASE / USD',st('给收入留出时间，也把等待成本算进去。','Allow time for revenue—and account for the cost of waiting.'),st('同一产品、项目组合及成本率；延后情景把全部项目与服务起点后移6个月，固定配置继续。收入、签约与收款分别计算。','The same products, project mix and costs. The delayed case shifts every project and service start six months while fixed resources continue. Revenue, contract value and cash remain separate.'))}${scenarioSwitch()}<div class="revenue-chart" role="img" aria-label="${st('三年收入对比，横轴0至120万美元','Three-year revenue; common scale0toUSD1.2million')}"><div class="chart-scale"><span>0</span><span>USD 600,000</span><span>USD 1,200,000</span></div>${c.years.map(x=>`<div class="revenue-row"><b>Y${x.year}</b><div class="revenue-track"><span style="width:${x.revenue/1200000*100}%"></span></div><strong>${fmt(x.revenue)}</strong></div>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>${st('指标 / USD','Metric / USD')}</th>${c.years.map(x=>`<th>Y${x.year}</th>`).join('')}</tr></thead><tbody>${[
['诊断 / 试点 / 生产验收数','Discovery / pilot / production acceptances',x=>`${x.completions.D} / ${x.completions.V} / ${x.completions.E}`],
['项目签约额（不含后续订阅）','Project contracts, excluding later subscriptions',x=>fmt(x.bookings)],
['规划收入','Planned revenue',x=>fmt(x.revenue)],
['其中：持续服务收入','Recurring service component',x=>fmt(x.support_revenue)],
['规划收款','Planned receipts',x=>fmt(x.receipts)],
['当期直接交付/服务成本','Current direct delivery / service costs',x=>fmt(x.direct)],
['区域固定配置','Regional fixed resources',x=>fmt(x.fixed)],['项目交付调配池 / 人','Project delivery resource pool / people',x=>String(x.delivery_staff_pool)],
['税前经营贡献','Pre-tax operating contribution',x=>fmt(x.contribution)]
].map(x=>`<tr><td>${st(x[0],x[1])}</td>${c.years.map(y=>`<td>${x[2](y)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="two"><section class="card"><h3>${st('36个月峰值经营现金缺口','Peak36-month operating cash gap')}</h3><p class="model-number">USD${fmt(c.peak_operating_cash_gap)}</p><p>${st('按月收入、收款和成本时点计算；加15%资金缓冲约','Calculated from monthly receipts and costs; with15% liquidity buffer, about ')}USD${fmt(c.liquidity_with_15pct)}。</p></section><section class="card"><h3>${st('企业底盘与战略上行分开','Enterprise base and strategic upside')}</h3><p>${st('上述只覆盖企业诊断、试点、受控生产实施和服务。国家/行业平台、JV资本、硬件及渠道佣金另行立项；三年愿景不依靠首年拿下大平台维持。','This base covers enterprise discovery, pilot, bounded production and services. National / industry platforms, JV capital, hardware and channel commissions require separate work. The three-year vision does not depend on a first-year major platform win.')}</p></section></div><p class="sales-small">${st('基准Y3年度转正不等于三年累计回本；当前企业底盘的三年累计税前贡献仍为负，详见第06项。','A positive baseY3does not mean cumulative three-year payback. Cumulative enterprise-base contribution remains negative; see section06.')}</p><details class="operating-layer"><summary>${st('展开计算依据、能力和会计口径','Calculation, capacity and accounting assumptions')}</summary><p>${st('价格为规划中值：诊断15,000、试点55,000、生产180,000；生产验收次月起服务3,000/月，直接服务成本900/月。服务成本900美元由每月1个人日支持700美元及基础云/监测200美元构成，仅覆盖工作日窗口；范围外支持另报价。项目验收计入规划收入，实施期直接成本费用化，用于呈现等待和资金压力；实际财务按合同安排。','Planning prices: discovery15,000; pilot55,000; production180,000; post-acceptance support3,000/month with900directcost. The USD900service cost is one person-day of business-hours support (700) and basic cloud / monitoring (200); additional support is priced separately. Planned revenue is recorded at acceptance and delivery costs during implementation, exposing timing pressure; actual accounting follows contracts.')}</p><p>${st('Y3基准峰值约3.68名项目交付FTE、最多两个生产项目并行；来自按月人周/4.33换算。按80%项目可用度，Y1/Y2/Y3建议调配约2/3/5名交付人员，按项目调用并计入直接成本。总部非计费售前另在固定资源中，持续服务按上线数量配置支持。','Y3base peak is about3.68project-delivery FTE, with at most two production scopes active. Derived from monthly person-weeks/4.33. At80%project availability, round theY1/Y2/Y3delivery pool to about2/3/5people, called off by project and included in direct costs. Non-billable presales is in fixed resources; service support scales with live projects.')}</p><p>${st('区域15%预算预留不自动计入损益；流动性缓冲与年度预留是不同观察角度，不叠加成第二笔费用。股东利润、平台利润与区域贡献分别核算。','The15% regional reserve is not automatically expensed. Liquidity buffer and annual reserve are alternative funding views, not duplicate costs. Shareholder profit, platform profit and regional contribution remain separate.')}</p><a href="files/strategy-model-v3.5.json">${st('模型与逐项假设JSON ↗','Model and assumptionsJSON ↗')}</a> · <a href="files/strategy-monthly-v3.5-${planCase}.csv">${st('月度收支CSV ↗','Monthly cash and costCSV ↗')}</a></details></section>`;}
function salesPipeline(){return intro('04 / PRODUCTS · CAPACITY · THREE YEARS',st('把三年愿景，拆成能承接的项目组合。','Turn the three-year vision into a deliverable project mix.'),st('Y1建立关系与首批验证，Y2生产落地，Y3复制服务。保留延期情景与资金安排，不用短期技术作业量替代完整市场周期。','Y1establishes relationships and initial validation, Y2production, Y3replication and services. Retain delays and funding needs; technical work effort is not the full market-development cycle.'))+planningVision()+financialPath()+`<section class="editorial-section">${sectionHeading('COMMERCIAL WORKFLOW',st('销售阶段独立于时间表。','Commercial stages are distinct from the calendar.'))}<div class="stage-register">${salesGates.map(x=>`<section><span>${x[0]}</span><h3>${st(x[1],x[2])}</h3><p>${st(x[3],x[4])}</p></section>`).join('')}</div></section><section class="pricing-panel"><div class="eyebrow">H35 / PRODUCT WORKLOAD ASSUMPTIONS</div><h2>${st('价格从边界和人周推导。','Price follows scope and person-weeks.')}</h2><div class="tablewrap"><table><thead><tr><th>${st('产品','Product')}</th><th>${st('报价推演 / USD','Price construction / USD')}</th><th>${st('中值 / USD','Planning point / USD')}</th></tr></thead><tbody>${Object.values(STRATEGY_MODEL.products).map(p=>`<tr><td>${st(p.zh,p.en)}<p class="sales-small">${sv(p.scope)}</p></td><td>${p.person_weeks}×${fmt(p.weekly_cost)}＋${fmt(p.external)}；×1.15${st('作交付缓冲，再按35%目标毛利校核。','delivery buffer; check against35% target margin.')}</td><td>${fmt(p.price)}</td></tr>`).join('')}</tbody></table></div><p class="sales-small">${st('单价与成本率为方案估值；诊断、试点、生产是独立付费权益。若前项费用抵扣后项，净合同及后续款项只扣一次。持续服务只计包外新增部分。','Rates and costs are planning estimates. Discovery, pilot and production are distinct paid scopes. Credit a preceding fee once against net contract / receipts if agreed. Support includes only incremental services outside implementation.')}</p></section>`;}
function salesReadiness(){return `<section class="editorial-section" id="readiness">${sectionHeading('FUNDING TIME / RESOURCE RELEASE',st('预算支持持续在场，不押注90天成交。','Fund sustained presence, without a90-day sales deadline.'))}<div class="sales-cash-band"><h2>USD${fmt(STRATEGY_MODEL.base_fixed[0]*1.15)}</h2><p>${st('Y1区域固定资源及15%预留；首3个月估值约USD69,748用于熟悉产品、关系经营、材料与演示。付费项目交付按直接成本另列。','Y1regional fixed resources plus15% reserve. AboutUSD69,748for the first three months supports orientation, relationships, materials and demos. Paid project delivery is a separate direct cost.')}</p></div><details class="operating-layer"><summary>${st('展开三年资源工作量与预算 / USD','Three-year workload and resource budget / USD')}</summary><div class="tablewrap"><table><thead><tr><th>${st('资源','Resource')}</th><th>${st('配置依据','Workload basis')}</th><th>Y1</th><th>Y2</th><th>Y3</th></tr></thead><tbody>${STRATEGY_MODEL.budget_rows.map(x=>`<tr><td>${st(x[0],x[1])}</td><td>${st(x[2],x[3])}</td>${x.slice(4).map(z=>`<td>${fmt(z)}</td>`).join('')}</tr>`).join('')}<tr><th>${st('基础配置合计','Base resources')}</th><td></td>${STRATEGY_MODEL.base_fixed.map(x=>`<th>${fmt(x)}</th>`).join('')}</tr><tr><th>${st('含15%预留','With15%reserve')}</th><td></td>${STRATEGY_MODEL.base_fixed.map(x=>`<th>${fmt(x*1.15)}</th>`).join('')}</tr></tbody></table></div><p>${st('按半年安排资源、按季度复盘。前三个月是启动资源的一部分，不能与全年预算重复相加；对接未进入深度阶段时，售前与出访按实际排期调整。数值为规划成本，不代表布比实际成本或个人薪酬要求。','Allocate by half-year and review quarterly. The first-quarter allowance is included in the annual budget. Adjust presales and visits when engagement is not yet deep. Values are planning costs, not actual BUBIX costs or personal compensation demands.')}</p></details></section>`;}
function salesDelivery(){return intro('05 / PROJECT EFFORT ≠ CUSTOMER CALENDAR',st('技术作业按周安排，客户项目按月协同。','Plan technical work in weeks; coordinate customer projects in months.'),st('两周诊断与六周试点描述受控范围内的有效技术作业量。客户会面、合同、数据、安全、复核与付款都有各自排期；完整项目周期另计。','Two-week discovery and six-week pilot describe active technical work for bounded scopes. Meetings, contracts, data, security, review and payment have separate schedules; the full customer journey is longer.'))+`<div class="two"><section class="card"><h2>${st('诊断：2个有效周 / 4–8周日历','Discovery:2activeweeks / 4–8calendarweeks')}</h2><p>${st('范围沟通与资料收集→内部分析→客户复核与调整→成果确认。模型安排两个月，主动分析约2.5人周。客户协调与等待不等于两个月全员驻场。','Scope / information → internal analysis → customer review / iteration → acceptance. Modelled at two months and about2.5person-weeks of active analysis, not full-time onsite staffing throughout.')}</p></section><section class="card"><h2>${st('试点：6个有效周 / 8–16周日历','Pilot:6activeweeks / 8–16calendarweeks')}</h2><p>${st('合同、首款、数据/接口及双方负责人具备后安排技术作业；基准预留三个月，需求或数据变化时滚动到四个月以上。','Schedule technical work after contract, payment, data / interfaces and both teams are ready. The base allows three months; changing requirements or data may extend it beyond four.')}</p></section></div><section class="editorial-section">${sectionHeading('FOUR CLOCKS / ONE JOINT SCHEDULE',st('四只时钟，共同决定交付日期。','Four clocks determine the agreed delivery date.'))}<div class="delivery-weeks">${[
['01','市场关系','Relationship cycle','从M1开始，按12–24个月经营；包含介绍、熟悉、赞助、工作组和采购共识。','FromM1across12–24months: introductions, familiarity, sponsorship, teams and procurement alignment.'],
['02','客户准备','Customer readiness','审批、合同、首款、样本数据和接口负责人；进度由双方共同安排。','Approvals, contract, initial payment, sample data and interface owners; jointly scheduled.'],
['03','内部有效作业','Active technical work','T1基线；T2–3构建；T4联调；T5修正；T6交接准备。T为有效作业周，不是连续自然周。','T1baseline; T2–3build; T4integration; T5fixes; T6handover preparation. Tmeans active workweeks, not consecutive calendar weeks.'],
['04','客户验收与付款','Acceptance and payment','安排评审、缺陷闭环、签署与付款；收款日期按合同账期另列。','Allow reviews, defect closure, signatures and payments; receipts follow contractual payment periods.']
].map(x=>`<section><b>${x[0]}</b><h3>${st(x[1],x[2])}</h3><p>${st(x[3],x[4])}</p></section>`).join('')}</div></section><div class="notice">${st('试点边界：一种凭证、两类参与方、最多3个约定接口与一个工作流，测试环境优先。生产迁移、更多接口、多机构治理另设范围与资源。客户排期变化先重排日历；范围变化另评估费用。','Pilot boundary: one credential, two participant types, up to three agreed interfaces and one workflow, prioritizing a test environment. Production migration, additional interfaces and multi-institution governance require separate scope / resources. Calendar changes reset dates; scope changes also reset pricing.')}</div><div class="two"><section class="card"><h3>${st('业务与技术验收','Business and technical acceptance')}</h3><p>${st('双方按工作流、权限、正常/异常样例和记录追溯评审；性能按实际环境和验收目标测试。','Both teams review workflow, permissions, normal / exception cases and traceability; test performance against the actual environment and acceptance targets.')}</p></section><section class="card"><h3>${st('商务与交接','Commercial acceptance and handover')}</h3><p>${st('交付资料、培训、遗留事项与服务责任写入交接；付款依合同里程碑管理，不把技术完成等同现金到账。','Document handover, training, open items and support responsibilities; manage payments by contractual milestones, separate from technical completion.')}</p></section></div>`;}
function salesCollections(){const c=STRATEGY_MODEL.cases[planCase],cum=c.years.reduce((a,x)=>a+x.contribution,0);return intro('06 / CASH · CONTRIBUTION · CAPITAL',st('回款跟随客户日历，资金覆盖完整周期。','Cash follows the customer calendar. Funding covers the full cycle.'),st('付款条件是商务方案的一部分；收款时间按合同与客户流程排期。年度收入、现金与累计回本是三件不同的事。','Payment terms belong in the commercial proposal; receipts follow contracts and counterpart processes. Annual revenue, cash and cumulative payback are distinct.'))+scenarioSwitch()+`<div class="two"><section class="card"><h3>${st('基准产品付款安排','Base product payment proposals')}</h3><p>${st('诊断：60%启动、40%验收后一个月；试点：40%启动、50%验收后一个月、10%稳定期后；生产：30%启动、40%中期、20%验收后、10%稳定期后。均为可谈判的方案假设。','Discovery:60%at start,40%one month after acceptance. Pilot:40%at start,50%one month after acceptance,10%after stabilization. Production:30%at start,40%midpoint,20%after acceptance,10%after stabilization. All are negotiable planning terms.')}</p></section><section class="card"><h3>${st('第一年基准收款','Year-one base receipts')}</h3><p>${st('两个15,000美元诊断与一个55,000美元试点，合计项目收入85,000美元；按模型付款时点Y1收款79,500美元，余款进入Y2。订单、收入和收款不混算。','TwoUSD15,000discovery scopes and oneUSD55,000pilot yieldUSD85,000project revenue. ModelledY1receipts areUSD79,500with the remaining milestone inY2. Keep contracts, revenue and receipts distinct.')}</p></section></div><div class="sales-cash-band"><h2>USD${fmt(c.liquidity_with_15pct)}</h2><p>${st('所选情景的36个月峰值现金缺口加15%缓冲，按月计算。是可用流动性安排，不是一次性费用，也不与年度资源预留重复相加。','Selected case: peak36-month cash gap plus15%buffer, calculated monthly. This is available liquidity, not a one-time expense or an addition to the same annual resource reserve.')}</p></div><div class="two"><section class="card"><h3>${st('三年累计税前经营贡献','Cumulative three-year pre-tax contribution')}</h3><p class="model-number">USD${fmt(cum)}</p><p>${st('基准Y3年度贡献转正，但三年累计尚未回本；延后情景第三年仍处培育与交付期。平台上行须有独立产品与资源模型，不能自动补足这一差距。','BaseY3annual contribution is positive, while three-year cumulative payback has not been achieved. The delayed case remains in development / delivery inY3. Platform upside requires its own product and resource model; it does not automatically close this gap.')}</p></section><section class="card"><h3>${st('资金、费用与股东收益','Funding, expenses and shareholder returns')}</h3><p>${st('区域固定配置、项目直接交付和流动性分别管理；供应商收入、运营平台收入和股权回报分别核算。历史500–1000万美元平台资本包不并入当前企业项目启动费用。','Manage fixed regional resources, direct delivery and liquidity separately. Distinguish supplier revenue, platform revenue and equity returns. The historicalUSD5–10million platform-capital concept is separate from enterprise mobilization spending.')}</p></section></div><section class="editorial-section">${sectionHeading('OPERATING RHYTHM',st('把复盘安排在人的节奏里。','Build reviews around a sustainable working rhythm.'))}<p>${st('每月更新项目与资金，重大客户排期变化及时重排；每季度综合复盘合作质量、交付负荷与费用；每半年决定下一期配置。日常跟进时间与对方约定，避免把催办次数作为业绩。','Update projects and cash monthly, rescheduling material customer changes promptly. Review cooperation quality, delivery load and spending quarterly; authorize the next resource period every half-year. Agree follow-ups with counterparts rather than counting reminders as performance.')}</p></section>`;}
function bindSales(){document.querySelectorAll('[data-scenario]').forEach(x=>x.onclick=()=>{planCase=x.dataset.scenario;render()});document.querySelectorAll('[data-route]').forEach(x=>x.onclick=()=>{activeRoute=x.dataset.route;render()});document.querySelectorAll('[data-account-ref]').forEach(x=>x.onclick=()=>{salesKind='all';go('resources');requestAnimationFrame(()=>document.getElementById('account-'+x.dataset.accountRef)?.scrollIntoView({block:'start'}))});document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));document.querySelectorAll('[data-kind]').forEach(x=>x.onclick=()=>{salesKind=x.dataset.kind;render()});document.querySelectorAll('[data-phase]').forEach(x=>x.onclick=()=>{salesPhase=+x.dataset.phase;render()});const credit=document.querySelector('#scopingCredit');if(credit){const update=()=>{document.querySelector('#salesScenario').innerHTML=`<div class="sales-counts"><div><b>${credit.checked?'50,000–85,000':'60,000–105,000'}</b><span>${st('USD / 拟定净合同情景','USD / proposed net-contract scenario')}</span></div><div><b>${credit.checked?st('重排','Recalculate'):'28,000–50,000'}</b><span>${credit.checked?st('抵扣后按净合同重排首款','Rebuild initial payments after credits'):st('USD / 独立合同首款情景','USD / initial-payment scenario')}</span></div></div>`};credit.onchange=update;update();}}
const legacySalesRender=render;
render=function(){const view=location.hash.slice(1)||'overview',query=document.querySelector('#search').value.trim();const custom={overview:salesOverview,resources:salesResources,execution:salesExecution,pipeline:salesPipeline,delivery:salesDelivery,collections:salesCollections};if(custom[view]&&!query){motionCleanup();document.querySelector('#app').innerHTML=custom[view]();bindVisual();}else legacySalesRender();if(query){const currentViews=[['execution',salesExecution],['pipeline',salesPipeline],['delivery',salesDelivery],['collections',salesCollections]];const hits=currentViews.filter(([id,fn])=>{const el=document.createElement('div');el.innerHTML=fn();return el.textContent.toLowerCase().includes(query.toLowerCase())});document.querySelector('#app').insertAdjacentHTML('afterbegin',`<section class="card"><h2>${st('v3.5当前规划检索','Current v3.5 plan results')}</h2>${hits.map(([id])=>`<button class="btn" data-go="${id}">${salesNav.find(x=>x[0]===id)[1]}</button>`).join('')}<p>${st('以下搜索同时包含历史附件；当前三年节奏与企业模型以03–06项为准。','Search also includes historical references. Sections03–06 govern the current three-year cadence and enterprise model.')}</p></section>`);} if(query){const matches=SALES_DATA.accounts.filter(a=>JSON.stringify(a).toLowerCase().includes(query.toLowerCase()));if(matches.length)document.querySelector('#app').insertAdjacentHTML('afterbegin',`<section class="card"><h2>${st('目标客户检索','Target-account search')}</h2>${matches.map(a=>`<button class="search-result" data-account-ref="${a.id}">${esc(accountName(a))}<p>${sv(a.offer)}</p></button>`).join('')}</section>`);}document.querySelector('#nav').innerHTML=salesNav.map(([id,t],i)=>`<button data-go="${id}" class="${view===id?'active':''}" aria-current="${view===id?'page':'false'}"><b>${String(i+1).padStart(2,'0')}</b>${t}</button>`).join('');if(!query&&['manual','v3model','calculator','history'].includes(view))document.querySelector('#app').insertAdjacentHTML('afterbegin',`<div class="sales-boundary">${st('v3.2作为历史平台/供货假设附件保留；其Y1–Y3为经营阶段。当前v3.5的Y1–Y3是连续12个月，企业项目与区域成本以02–06项为准，两个口径不互换。','The v3.2 platform / supplier model is historical and uses operating stages. Current v3.5 years are successive12-monthperiods; sections02–06 govern enterprise projects and regional costs. Do not interchange these bases.')}</div>`);if(!query&&view==='sources')document.querySelector('#app').insertAdjacentHTML('afterbegin',`<section class="card"><h2>${st('v3.5中东资源与Wasta依据','v3.5 Middle East resources and Wasta evidence')}</h2><p>${st('关系通路材料、直接入口确认、Wasta背景研究、公开职务与规划建议分别记录；公共职务不证明私人关系或采购授权。','Separate relationship materials, direct-access confirmation, Wasta research, public offices and recommendations. Public office does not prove a private relationship or procurement authority.')}</p><a class="btn" href="files/strategy-checks-v3.5.json">${st('算术复核记录JSON','Arithmetic checksJSON')}</a><a class="btn" href="files/strategy-model-v3.5.json">${st('三年规划模型JSON','Three-year modelJSON')}</a><a class="btn" href="files/sales-targets-v3.5.json">${st('目标客户与来源登记JSON','Accounts and source register JSON')}</a><a class="btn" href="files/sales-action-plan-v3.5-${salesEn?'en':'zh'}.txt">${st('销售行动提要','Sales action brief')}</a></section>`);bindSales();};
window.removeEventListener('hashchange',legacySalesRender);window.addEventListener('hashchange',render);document.querySelector('#search').oninput=render;render();
